#include <bits/stdc++.h>
std::vector<int> round_down_scores(const std::vector<double>& student_scores) { std::vector<int> result(student_scores.size()); std::transform(student_scores.begin(), student_scores.end(), result.begin(), [](const double& score) { return static_cast<int>(score); });return result;}
int count_failed_students(const std::vector<int>& student_scores) { return std::count_if( student_scores.begin(), student_scores.end(), [](const int& score) { return score <= 40; });}
std::array<int, 4> letter_grades(const int& highest_score) { std::array<int, 4> thresholds; const int interval = (highest_score - 40) / thresholds.size(); std::generate(thresholds.begin(), thresholds.end(), [threshold = 41 - interval, &interval] () mutable { return threshold += interval; }); return thresholds;}
std::vector<std::string> student_ranking(const std::vector<int>& student_scores, const std::vector<std::string>& student_names) { assert(student_scores.size() == student_names.size()); std::vector<std::string> result(student_scores.size()); std::transform( student_scores.begin(), student_scores.end(), student_names.begin(), result.begin(), [rank = 1](const int& score, const std::string& name) mutable { return std::to_string(rank++) + ". " + name + ": " + std::to_string(score); }); return result; }
std::string perfect_score(const std::vector<int>& student_scores, const std::vector<std::string>& student_names) { auto it = std::find(student_scores.begin(), student_scores.end(), 100); return it != student_scores.end() ? student_names.at(std::distance(student_scores.begin(), it)) : "";}